-- Migração 29 (cw_prod): bloqueio de login após 4 tentativas e premissas de proteção por cliente. Cole no SQL Editor e execute.
begin;
-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 20: login lockout after 4 failed attempts (S7) and per-client protection assumptions (A5). Additive.

-- ---------------------------------------------------------------- login lockout (S7, D-055)
-- Failed attempts by e-mail hash only (no personal data). 4 failures in 15 minutes lock that e-mail for 15 minutes;
-- 8 in an hour lock it for an hour. The lock is checked before asking Supabase Auth, so it answers the same whether
-- or not the account exists (no account oracle). A successful login clears the counter.
create table cw_prod_private.login_failures (
  email_sha256 text not null check (email_sha256 ~ '^[0-9a-f]{64}$'),
  failed_at    timestamptz not null default now()
);
create index login_failures_hash_idx on cw_prod_private.login_failures (email_sha256, failed_at desc);
alter table cw_prod_private.login_failures enable row level security;
alter table cw_prod_private.login_failures force row level security;
revoke all on cw_prod_private.login_failures from public, anon, authenticated;
grant all on cw_prod_private.login_failures to service_role;

create or replace function cw_prod.service_record_failed_login(p_email_sha256 text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if p_email_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'invalid' using errcode = '22023'; end if;
  insert into cw_prod_private.login_failures (email_sha256) values (p_email_sha256);
  delete from cw_prod_private.login_failures where failed_at < now() - interval '1 day';   -- keeps the table small
  perform cw_prod_private.write_audit('FAILED_LOGIN', 'auth', p_email_sha256, null, null, null);
end $$;

-- Seconds until the e-mail may try again (0 = allowed).
create function cw_prod.service_login_lock_seconds(p_email_sha256 text) returns integer
language plpgsql stable security definer set search_path = '' as $$
declare v_15 timestamptz; v_60 timestamptz; v_until timestamptz;
begin
  if p_email_sha256 !~ '^[0-9a-f]{64}$' then raise exception 'invalid' using errcode = '22023'; end if;
  -- the 4th most recent failure inside 15 minutes / the 8th inside one hour
  select failed_at into v_15 from cw_prod_private.login_failures where email_sha256 = p_email_sha256 and failed_at > now() - interval '15 minutes'
   order by failed_at desc offset 3 limit 1;
  select failed_at into v_60 from cw_prod_private.login_failures where email_sha256 = p_email_sha256 and failed_at > now() - interval '1 hour'
   order by failed_at desc offset 7 limit 1;
  v_until := greatest(v_15 + interval '15 minutes', v_60 + interval '1 hour');
  if v_until is null or v_until <= now() then return 0; end if;
  return ceil(extract(epoch from v_until - now()))::integer;
end $$;

create function cw_prod.service_clear_login_failures(p_email_sha256 text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  delete from cw_prod_private.login_failures where email_sha256 = p_email_sha256;
end $$;

revoke all on function cw_prod.service_login_lock_seconds(text), cw_prod.service_clear_login_failures(text) from public, anon, authenticated;
grant execute on function cw_prod.service_login_lock_seconds(text), cw_prod.service_clear_login_failures(text) to service_role;
revoke all on function cw_prod.service_record_failed_login(text) from public, anon, authenticated;
grant execute on function cw_prod.service_record_failed_login(text) to service_role;

-- ---------------------------------------------------------------- protection assumptions per client (A5, D-055)
-- Defaults are the values the analysis used until now; the consultant adjusts them to the family's reality.
create table cw_prod.protection_profiles (
  client_id                 uuid primary key references cw_prod.clients (id) on delete cascade,
  dependent_support_age     smallint not null default 24 check (dependent_support_age between 18 and 30),
  spouse_support_years      smallint not null default 5 check (spouse_support_years between 0 and 40),
  real_rate_pct             numeric(5,2) not null default 4 check (real_rate_pct between 0 and 10),
  disability_max_years      smallint not null default 10 check (disability_max_years between 1 and 40),
  disability_liquid_offset_pct numeric(5,2) not null default 50 check (disability_liquid_offset_pct between 0 and 100),
  critical_illness_months   smallint not null default 12 check (critical_illness_months between 0 and 60),
  extra_life_need           numeric(18,2) not null default 0 check (extra_life_need >= 0 and extra_life_need < 1e12),
  notes                     text check (length(notes) <= 1000),
  updated_by                uuid,
  updated_at                timestamptz not null default now()
);
alter table cw_prod.protection_profiles enable row level security;
alter table cw_prod.protection_profiles force row level security;
create policy protection_profiles_read on cw_prod.protection_profiles for select to authenticated using ((select cw_prod_private.can_access_client(client_id)));
revoke all on cw_prod.protection_profiles from public, anon, authenticated;
grant select on cw_prod.protection_profiles to authenticated;
grant all on cw_prod.protection_profiles to service_role;
create trigger t_audit after insert or update or delete on cw_prod.protection_profiles for each row execute function cw_prod_private.audit_row();

create function cw_prod.protection_profile_save(p_client uuid, p_data jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_client(p_client);
  insert into cw_prod.protection_profiles as p (client_id, dependent_support_age, spouse_support_years, real_rate_pct, disability_max_years,
    disability_liquid_offset_pct, critical_illness_months, extra_life_need, notes, updated_by)
  values (p_client, (p_data ->> 'dependent_support_age')::smallint, (p_data ->> 'spouse_support_years')::smallint, (p_data ->> 'real_rate_pct')::numeric,
    (p_data ->> 'disability_max_years')::smallint, (p_data ->> 'disability_liquid_offset_pct')::numeric, (p_data ->> 'critical_illness_months')::smallint,
    coalesce(nullif(p_data ->> 'extra_life_need', '')::numeric, 0), nullif(btrim(p_data ->> 'notes'), ''), auth.uid())
  on conflict (client_id) do update set dependent_support_age = excluded.dependent_support_age, spouse_support_years = excluded.spouse_support_years,
    real_rate_pct = excluded.real_rate_pct, disability_max_years = excluded.disability_max_years,
    disability_liquid_offset_pct = excluded.disability_liquid_offset_pct, critical_illness_months = excluded.critical_illness_months,
    extra_life_need = excluded.extra_life_need, notes = excluded.notes, updated_by = auth.uid(), updated_at = now();
end $$;
revoke all on function cw_prod.protection_profile_save(uuid, jsonb) from public, anon, authenticated;
grant execute on function cw_prod.protection_profile_save(uuid, jsonb) to authenticated;
commit;
select 'migração 29 ok' as resultado, to_regclass('cw_prod.protection_profiles') is not null as premissas, to_regclass('cw_prod_private.login_failures') is not null as bloqueio;
